 chgDirPath         CMM0070.CM_DIRPATH%TYPE;                 
 SvDirpath          CMM0070.CM_DIRPATH%TYPE;                 
 SvDirpath2         CMM0070.CM_DIRPATH%TYPE;                 
 SvHomeDir          CMM0070.CM_DIRPATH%TYPE;                 
 SvSvrIp            CMM0031.CM_SVRIP%TYPE;                 
