 SvSvrCd            CMM0031.CM_SVRCD%TYPE;                 
 WKSVRIP            CMM0031.CM_SVRIP%TYPE;                 
 FINDSW             BOOLEAN;                   
 VCNT               INTEGER;                
                     
CURSOR  Conf1 IS                    
    SELECT /*+NO_EXPAND LEADING(C E)*/        
           e.cm_svrip,e.cm_portno,e.cm_syscd,e.cm_svrcd,e.cm_seqno,f.cm_rsrccd,A.CM_DIRPATH,a.cm_dsncd, e.cm_sysos               
