                                     AND CM_SYSCD=DECODE(SYSCD,'ALL',CM_SYSCD,SYSCD)               
                                     AND CM_SVRCD ='05'    
                                     AND CM_SVRIP=DECODE(WKSVRIP,'ALL',CM_SVRIP,WKSVRIP))                     
               AND Z.CM_RUNCD='01'                    
               AND Z.CM_EXISTYN='N'                       
               AND Y.CR_SYSCD=Z.CM_SYSCD                
               AND y.cr_lstver>0                    
               and y.cr_status<>'9'                    
               and y.cr_syscd=x.cm_syscd                    
               and y.cr_dsncd=x.cm_dsncd        
             group by y.cr_syscd,y.cr_rsrccd,x.cm_dirpath,x.cm_dsncd) a,                    
           cmm0030 b              
          , cmm0036 J        
     where b.cm_closedt is null                    
       AND B.CM_SYSCD=DECODE(SYSCD,'ALL',B.CM_SYSCD,SYSCD)                    
       AND b.cm_syscd=e.cm_syscd                    
       and e.cm_closedt is null                    
       AND E.CM_SVRIP=DECODE(WKSVRIP,'ALL',E.CM_SVRIP,WKSVRIP)                    
