       and e.cm_syscd=f.cm_syscd                    
       and e.cm_svrcd=f.cm_svrcd                    
       and e.cm_seqno=f.cm_seqno                    
       and f.cm_syscd=a.cr_syscd                    
       and f.cm_rsrccd=a.cr_rsrccd           
       and a.cr_syscd = J.cm_syscd       
       and a.cr_rsrccd = J.cm_rsrccd       
