           AND B.CM_RUNCD='01'                    
           AND B.CM_EXISTYN='N'                    
           AND B.CM_SYSCD=A.CM_SYSCD                    
           AND A.CM_CLOSEDT IS NULL                    
           AND A.CM_SVRCD IN ('03','05');              
                               
    IF SVRIP IS NULL THEN                    
       WKSVRIP := 'ALL';                    
    ELSE                    
       WKSVRIP := SVRIP;                    
