--           ELSE                    
              SvDirpath2 := Dir.CM_DIRPATH;                    
--           END IF;        
                  
           SvDirpath := CHG_DIRPATH(Dir.CM_SYSCD,Dir.CM_SVRCD,Dir.CM_SEQNO,Dir.CM_SVRIP,Dir.CM_PORTNO,Dir.CM_RSRCCD,SvDirpath2,'');                    
                  
           IF SUBSTR(SvDirpath,1,1) <> '/'  AND Dir.CM_SYSOS = '01' THEN                    
              SvDirpath := '/' || SvDirpath;                    
