           SvSvrIp := Dir.CM_SVRIP;                    
           SvSysCd := Dir.CM_SYSCD;               
           SvSvrCd := Dir.CM_SVRCD;               
           chgDirPath := Dir.CM_DIRPATH;       
                  
           SvDsnCd := Dir.CM_DSNCD;                    
           IF DIRCD = 'C' THEN                    
              FINDSW := FALSE;                    
           END IF;                    
        ELSIF DIRCD = 'C' THEN                    
            IF SvSysCd <> Dir.CM_SYSCD OR SvSvrIp <> Dir.CM_SVRIP OR SvSvrCd <> Dir.CM_SVRCD OR chgDirPath <> Dir.CM_DIRPATH THEN                    
               FINDSW := FALSE;                    
            END IF;                               
        ELSIF SvSysCd <> Dir.CM_SYSCD OR SvSvrIp <> Dir.CM_SVRIP THEN                            
           FINDSW := FALSE;                    
        END IF;                    
                              
        IF FINDSW = TRUE AND DIRCD <> 'C' THEN                    
           FINDSW := FALSE;                    
--           IF SUBSTR(Dir.CM_DIRPATH,1,1) <> '/'  AND Dir.CM_SYSOS = '01' THEN                    
