--           ELSE                    
              SvDirpath2 := Dir.CM_DIRPATH;                    
--           END IF;                    
           SvDirpath2 := CHG_DIRPATH(Dir.CM_SYSCD,Dir.CM_SVRCD,Dir.CM_SEQNO,Dir.CM_SVRIP,Dir.CM_PORTNO,Dir.CM_RSRCCD,SvDirpath2,'');                    
           IF SUBSTR(SvDirpath2,1,1) <> '/'  AND Dir.CM_SYSOS = '01' THEN                    
              SvDirpath2 := '/' || SvDirpath2;                    
           END IF;                    
           IF INSTR(SvDirpath2,'/',INSTR(SvDirpath2,'/',1,3)) > 0 THEN                    
              SvHomeDir := SUBSTR(SvDirpath2,1,INSTR(SvDirpath2,'/',1,3) -1);                    
           ELSE                    
              SvHomeDir := SvDirpath2;                    
           END IF;                    
                               
           IF LENGTH(SvDirpath) < LENGTH(SvHomeDir) THEN                    
              IF SUBSTR(SvHomeDir,1,LENGTH(SvDirpath)) <> SvDirpath THEN                    
                 FINDSW := TRUE;                      
              END IF;                    
           ELSIF LENGTH(SvDirpath) = LENGTH(SvHomeDir) THEN                    
              IF SvDirpath <> SvHomeDir THEN                    
                 FINDSW := TRUE;                    
