               SvDsnCd := Dir.CM_DSNCD;                    
               FINDSW := TRUE;                               
           END IF;                    
           IF SvSysCd <> Dir.CM_SYSCD OR SvSvrIp <> Dir.CM_SVRIP OR DIRCD = 'C' THEN                    
